H.IDB={n:'hrp-v9',db:null,fb:false,
async open(){if(!('indexedDB'in window)){this.fb=true;return;}return new Promise(r=>{const q=indexedDB.open(this.n,3);q.onupgradeneeded=e=>{const d=e.target.result;if(!d.objectStoreNames.contains('cases'))d.createObjectStore('cases',{keyPath:'id'});if(!d.objectStoreNames.contains('clinic'))d.createObjectStore('clinic',{keyPath:'id'});if(!d.objectStoreNames.contains('srs'))d.createObjectStore('srs',{keyPath:'id'});if(!d.objectStoreNames.contains('packs'))d.createObjectStore('packs',{keyPath:'id'});};q.onsuccess=e=>{this.db=e.target.result;r();};q.onerror=()=>{this.fb=true;r();};});},
async all(store){if(this.fb)return H.St.g('fb.'+store,[]);return new Promise(r=>{const q=this.db.transaction(store,'readonly').objectStore(store).getAll();q.onsuccess=()=>r(q.result||[]);q.onerror=()=>r([]);});},
async get(store,id){if(this.fb)return(H.St.g('fb.'+store,[])).find(c=>c.id===id);return new Promise(r=>{const q=this.db.transaction(store,'readonly').objectStore(store).get(id);q.onsuccess=()=>r(q.result||null);q.onerror=()=>r(null);});},
async put(store,c){if(this.fb){const a=H.St.g('fb.'+store,[]);const i=a.findIndex(x=>x.id===c.id);if(i>=0)a[i]=c;else a.unshift(c);if(a.length>10000)a.length=10000;H.St.s('fb.'+store,a);return;}return new Promise(r=>{const q=this.db.transaction(store,'readwrite').objectStore(store).put(c);q.onsuccess=()=>r();});},
async del(store,id){if(this.fb){H.St.s('fb.'+store,H.St.g('fb.'+store,[]).filter(c=>c.id!==id));return;}return new Promise(r=>{const q=this.db.transaction(store,'readwrite').objectStore(store).delete(id);q.onsuccess=()=>r();});}};
H.Clinic={
async save(data){const tags=(data.tags||[]).map(t=>t.trim().toLowerCase()).filter(Boolean);const c={id:data.id||Date.now().toString(36)+Math.random().toString(36).slice(2,6),name:data.name||'',age:data.age||'',gender:data.gender||'',phone:data.phone||'',email:data.email||'',complaint:data.complaint||'',notes:data.notes||'',status:data.status||'active',date:data.date||Date.now(),followups:data.followups||[],selectedIds:data.selectedIds||[],mode:data.mode||'acute',tags,lastExport:data.lastExport||null};await H.IDB.put('clinic',c);H.Stats.invalidate();return c;},
async all(){return await H.IDB.all('clinic');},
async get(id){return await H.IDB.get('clinic',id);},
async rm(id){await H.IDB.del('clinic',id);H.Stats.invalidate();},
async addFollowup(caseId,fu){const c=await this.get(caseId);if(!c)return;if(!c.followups)c.followups=[];c.followups.push({date:Date.now(),remedy:fu.remedy||'',potency:fu.potency||'',notes:fu.notes||''});c.followups.sort((a,b)=>b.date-a.date);await H.IDB.put('clinic',c);H.Stats.invalidate();return c;},
async setStatus(id,status){const c=await this.get(id);if(!c)return;c.status=status;await H.IDB.put('clinic',c);H.Stats.invalidate();return c;},
async setTags(id,tags){const c=await this.get(id);if(!c)return;c.tags=tags.map(t=>t.trim().toLowerCase()).filter(Boolean);await H.IDB.put('clinic',c);H.Stats.invalidate();return c;},
async export(id){const c=id?await this.get(id):await this.all();return JSON.stringify(c,null,2);},
async markExported(){H.St.s('lastClinicExport',Date.now());},
search(cases,query,status,tag){let filtered=cases;if(status&&status!=='all')filtered=filtered.filter(c=>c.status===status);if(tag&&tag!=='all')filtered=filtered.filter(c=>(c.tags||[]).includes(tag.toLowerCase()));if(query){const q=query.toLowerCase();filtered=filtered.filter(c=>c.name.toLowerCase().includes(q)||c.complaint.toLowerCase().includes(q)||(c.tags||[]).some(t=>t.includes(q)));}return filtered.sort((a,b)=>b.date-a.date);},
async findDuplicate(name){const cases=await this.all();const n=name.trim().toLowerCase();return cases.filter(c=>c.name.trim().toLowerCase()===n);},
sortCases(cases,sortBy){switch(sortBy){case 'name':return[...cases].sort((a,b)=>a.name.localeCompare(b.name));case 'status':return[...cases].sort((a,b)=>a.status.localeCompare(b.status));case 'date':default:return[...cases].sort((a,b)=>b.date-a.date);}},
getStale(cases){const cutoff=Date.now()-30*864e5;return cases.filter(c=>c.status==='active'&&(!c.followups?.length||c.followups[0].date<cutoff));}
};
