H.Stats={_cache:null,_ts:0,
invalidate(){this._cache=null;this._ts=0;},
async compute(){const now=Date.now();if(this._cache&&now-this._ts<30000)return this._cache;const cases=await H.Clinic.all();const total=cases.length;const active=cases.filter(c=>c.status==='active').length;const completed=cases.filter(c=>c.status==='completed').length;const archived=cases.filter(c=>c.status==='archived').length;const thisMonth=cases.filter(c=>{const d=new Date(c.date);const n=new Date();return d.getMonth()===n.getMonth()&&d.getFullYear()===n.getFullYear();}).length;const followupCount=cases.reduce((sum,c)=>sum+(c.followups?.length||0),0);const tags={};cases.forEach(c=>{(c.tags||[]).forEach(t=>{tags[t]=(tags[t]||0)+1;});});const topTags=Object.entries(tags).sort((a,b)=>b[1]-a[1]).slice(0,5);const stale=H.Clinic.getStale(cases).length;this._cache={total,active,completed,archived,thisMonth,followupCount,topTags,stale};this._ts=now;return this._cache;},
async render(){const s=await this.compute();const m=document.getElementById('md');m.innerHTML=`<div class="mh"><div><div class="mt">📊 Clinic Statistics</div></div><button class="ib" id="mc">✕</button></div><div class="mbd"><div class="stats-grid"><div class="stat-card"><div class="stat-num">${s.total}</div><div class="stat-label">Total Cases</div></div><div class="stat-card"><div class="stat-num">${s.active}</div><div class="stat-label">Active</div></div><div class="stat-card"><div class="stat-num">${s.completed}</div><div class="stat-label">Completed</div></div><div class="stat-card"><div class="stat-num">${s.archived}</div><div class="stat-label">Archived</div></div><div class="stat-card"><div class="stat-num">${s.thisMonth}</div><div class="stat-label">This Month</div></div><div class="stat-card"><div class="stat-num">${s.followupCount}</div><div class="stat-label">Follow-ups</div></div><div class="stat-card"><div class="stat-num" style="color:var(--wrn)">${s.stale}</div><div class="stat-label">Stale (30d)</div></div></div>${s.topTags.length?`<div class="msec"><h4>Top Tags</h4><div>${s.topTags.map(([t,c])=>`<span class="tag">${t} (${c})</span>`).join('')}</div></div>`:''}<div style="display:flex;gap:6px;margin-top:14px"><button class="btn bg" id="stats-usage">💊 Remedy Usage</button><button class="btn bg" id="stats-summary">📋 Active Summary</button><button class="btn bg" id="stats-close">Close</button></div></div>`;H.U.om();document.getElementById('mc').onclick=()=>H.U.cm();document.getElementById('stats-close').onclick=()=>H.U.cm();document.getElementById('stats-usage').onclick=()=>H.Usage.render();document.getElementById('stats-summary').onclick=()=>H.Summary.render();}
};
H.Usage={
async compute(){const cases=await H.Clinic.all();const usage={};cases.forEach(c=>{(c.followups||[]).forEach(f=>{if(f.remedy){const key=f.remedy.trim().toLowerCase();const display=f.remedy.trim();if(!usage[key])usage[key]={name:display,count:0,potencies:{}};usage[key].count++;if(f.potency)usage[key].potencies[f.potency]=(usage[key].potencies[f.potency]||0)+1;}});});return Object.values(usage).sort((a,b)=>b.count-a.count);},
async render(){const usage=await this.compute();const m=document.getElementById('md');const max=usage.length?usage[0].count:1;m.innerHTML=`<div class="mh"><div><div class="mt">💊 Remedy Usage Report</div><div class="msu">${usage.length} unique remedies prescribed</div></div><button class="ib" id="mc">✕</button></div><div class="mbd">${usage.length===0?'<div class="emp"><div class="emp-i">💊</div>No remedies prescribed yet.</div>':usage.slice(0,20).map(u=>`<div class="usage-row"><div class="usage-name">${u.name}</div><div style="flex:1"><div class="usage-bar"><div class="usage-fill" style="width:${Math.round(u.count/max*100)}%"></div></div></div><div class="usage-count">${u.count}</div></div>${Object.keys(u.potencies).length?`<div style="font-size:10px;color:var(--txt2);margin:-4px 0 6px 128px">${Object.entries(u.potencies).map(([p,c])=>`${p}×${c}`).join(' · ')}</div>`:''}`).join('')}</div>`;H.U.om();document.getElementById('mc').onclick=()=>H.U.cm();}
};
