async md(r,s,m){const S=H.DB.symptoms;const d=new Date().toLocaleString();let t=`# Highest Matching Remedies\n\n*${d} · ${m} · ${s.length} symptoms*\n\n> Educational ranking only.\n\n## Symptoms\n\n`;s.forEach(id=>{const n=S[id]?.name;if(n)t+=`- ${n}\n`;});t+='\n## Results\n\n';r.slice(0,25).forEach((x,i)=>{const rm=H.DB.remedies[x.code];t+=`### ${i+1}. ${rm.name} *(${rm.latin})*\n\n- Match: ${x.matchScore} · Confidence: ${x.confidence}% · Diff: ${x.diffScore}%\n\n*${rm.description}*\n\n---\n\n`;});return t;},
