rs(){const h=this.el('symptoms');const cats=this.s.cat?H.DB.cats.filter(c=>c.k===this.s.cat):H.DB.cats;const S=H.DB.symptoms;const q=this.s.q.toLowerCase();let html='';cats.forEach(cat=>{const syms=Object.values(S).filter(s=>s.cat===cat.k&&(!q||s.name.toLowerCase().includes(q)||s.synonyms.some(sy=>sy.toLowerCase().includes(q))));if(!syms.length)return;const open=this.s.open.has(cat.k);html+=`<div class="ss ${open?'open':''}" data-cat="${cat.k}"><button class="sh" aria-expanded="${open}"><span>${cat.e} ${cat.l}</span><span style="display:flex;align-items:center;gap:8px"><span class="ct">${syms.length}</span><span class="ch">▸</span></span></button><div class="sl">${syms.map(s=>`<label class="sc ${this.s.sel.has(s.id)?'sel':''}" data-sid="${s.id}"><input type="checkbox" ${this.s.sel.has(s.id)?'checked':''}/><span>${q?this.hl(s.name,q):s.name}</span></label>`).join('')}</div></div>`;});h.innerHTML=html||`<div class="emp"><div class="emp-i">🔎</div>No symptoms match.</div>`;},
